(() => {
  "use strict";
  // Published artifact contract: data/soi/daily-report.json (generated by the isolated SOI pipeline).
  const REPORT_URL = "/data/soi/daily-report.json";
  const $ = id => document.getElementById(id);
  const state = { rows: [], filter: "all", report: null };
  const number = value => Number.isFinite(Number(value)) ? new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(Number(value)) : "Нет данных";
  const money = value => Number.isFinite(Number(value)) ? "$" + number(value) : "Нет данных";
  const date = value => { if(!value)return "—"; const d=new Date(value); return Number.isNaN(d.getTime())?String(value):d.toLocaleString("ru-RU"); };
  const set = (id,value) => { const el=$(id); if(el) el.textContent=value; };
  const mintLink = mint => "https://solscan.io/token/"+encodeURIComponent(mint);
  const asArray = value => Array.isArray(value) ? value : [];
  function isPromoted(row){return Boolean(row.promotion?.observed || row.promotion?.boosted || row.promotion?.paid_order || row.promoted);}
  function noSocials(row){const socials=row.socials || {}; return socials.observed === true && !(socials.website || socials.twitter || socials.telegram || socials.discord || socials.other);}
  function reachedMillion(row){return Boolean(row.market_cap_milestone_1m?.reached || row.milestones?.market_cap_1m?.reached || Number(row.market_cap_usd)>=1000000);}
  function matches(row){
    if(state.filter==="no-socials")return noSocials(row);
    if(state.filter==="promoted")return isPromoted(row);
    if(state.filter==="million")return reachedMillion(row);
    return true;
  }
  function signal(text){const span=document.createElement("span");span.className="soi-signal";span.textContent=text;return span;}
  function renderRows(){
    const body=$("soi-launches"); if(!body)return;
    body.replaceChildren();
    const rows=state.rows.filter(matches);
    $("soi-empty").hidden=rows.length!==0;
    if(!rows.length){const tr=document.createElement("tr"),td=document.createElement("td");td.colSpan=6;td.textContent="Нет записей для выбранного фильтра.";tr.appendChild(td);body.appendChild(tr);return;}
    rows.slice(0,100).forEach(row=>{
      const tr=document.createElement("tr");
      const token=document.createElement("td");
      const name=document.createElement("span");name.className="token-name";name.textContent=[row.name,row.symbol?("("+row.symbol+")"):""].filter(Boolean).join(" ")||"Неизвестный токен";
      const mint=document.createElement("span");mint.className="token-mint";
      if(row.mint){const a=document.createElement("a");a.href=mintLink(row.mint);a.target="_blank";a.rel="noopener noreferrer";a.textContent=row.mint;mint.appendChild(a);}else mint.textContent="Mint не указан";
      token.append(name,mint);tr.appendChild(token);
      const launch=document.createElement("td");launch.textContent=[row.venue||"Площадка не определена",date(row.first_seen_at||row.launch_at)].join(" · ");tr.appendChild(launch);
      const cap=document.createElement("td");cap.textContent=money(row.market_cap_usd);tr.appendChild(cap);
      const liq=document.createElement("td");liq.textContent=money(row.liquidity_usd);tr.appendChild(liq);
      const hour=document.createElement("td");
      const h=row.first_hour||{};
      hour.textContent=h.status==="complete" ? (number(h.buy_count)+" покупок · "+number(h.sell_count)+" продаж · "+number(h.unique_buyers)+" покупателей") : (h.status==="partial"?"Неполное покрытие":"Нет подтверждённых снимков");
      tr.appendChild(hour);
      const signals=document.createElement("td");
      if(noSocials(row))signals.appendChild(signal("Соцссылки не найдены"));
      if(isPromoted(row))signals.appendChild(signal("Продвижение наблюдалось"));
      if(reachedMillion(row))signals.appendChild(signal("Market Cap $1 млн+"));
      if(!signals.childNodes.length)signals.textContent="Нет подтверждённых сигналов";
      tr.appendChild(signals);body.appendChild(tr);
    });
  }
  function render(report){
    state.report=report;
    state.rows=asArray(report.launches || report.tokens);
    const summary=report.summary||{};
    set("soi-count",number(summary.launches_detected ?? state.rows.length));
    set("soi-no-socials",number(summary.without_social_links ?? state.rows.filter(noSocials).length));
    set("soi-promoted",number(summary.promoted_launches ?? state.rows.filter(isPromoted).length));
    set("soi-million",number(summary.reached_market_cap_1m ?? state.rows.filter(reachedMillion).length));
    set("soi-report-date","Дата отчёта: "+(report.report_date||"—"));
    set("soi-report-updated","Обновлено: "+date(report.generated_at));
    const coverage=report.coverage||{};
    set("soi-coverage","Покрытие: "+(coverage.description||coverage.status||"не указано"));
    if(report.methodology) set("soi-method",report.methodology);
    const status=$("soi-status");status.dataset.state="ready";
    set("soi-status",report.status==="partial"?"Отчёт загружен · неполное покрытие":"Ежедневный отчёт загружен");
    renderRows();
  }
  async function load(){
    set("soi-status","Загрузка ежедневного отчёта…");
    try{
      const response=await fetch(REPORT_URL,{cache:"no-store",headers:{accept:"application/json"}});
      if(!response.ok)throw new Error(response.status===404?"отчёт ещё не опубликован":"HTTP "+response.status);
      const report=await response.json();
      if(!report || !Array.isArray(report.launches||report.tokens))throw new Error("неверный формат отчёта");
      render(report);
    }catch(error){
      const status=$("soi-status");if(status)status.dataset.state="error";
      set("soi-status","Данные пока не подключены: "+(error.message||"ошибка загрузки"));
      set("soi-count","—");set("soi-no-socials","—");set("soi-promoted","—");set("soi-million","—");
      set("soi-report-date","Дата отчёта: —");set("soi-report-updated","Обновлено: —");set("soi-coverage","Покрытие: отсутствует");
      const body=$("soi-launches");
      if(body){body.replaceChildren();const tr=document.createElement("tr"),td=document.createElement("td");td.colSpan=6;td.textContent="Проверенный ежедневный отчёт ещё не опубликован. Никакие тестовые или вымышленные токены здесь не показываются.";tr.appendChild(td);body.appendChild(tr);}
      set("soi-method","Сборщик SOI пока не подключён к публичной выдаче. После проверки живого сбора и архива отчёт будет публиковаться сюда отдельным JSON-файлом.");
    }
  }
  document.querySelectorAll("[data-soi-filter]").forEach(button=>button.addEventListener("click",()=>{
    state.filter=button.dataset.soiFilter;
    document.querySelectorAll("[data-soi-filter]").forEach(item=>item.classList.toggle("is-active",item===button));
    renderRows();
  }));
  load();
  window.setInterval(load,300000);
})();